+                Query query = new MultiMatchQueryBuilder("hello").tieBreaker(0.5f).toQuery(context);
+                Query expected = new DisjunctionMaxQuery(
+                    List.of(
+                        new TermQuery(new Term("f_text1", "hello")),
+                        new TermQuery(new Term("f_text2", "hello")),
